// HasLotteryCampaign applies the HasEdge predicate on the "lottery_campaign" edge.
func HasLotteryCampaign() predicate.RankingRewardCampaign {
	return predicate.RankingRewardCampaign(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, LotteryCampaignTable, LotteryCampaignColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasLotteryCampaignWith applies the HasEdge predicate on the "lottery_campaign" edge with a given conditions (other predicates).
func HasLotteryCampaignWith(preds ...predicate.LotteryCampaign) predicate.RankingRewardCampaign {
	return predicate.RankingRewardCampaign(func(s *sql.Selector) {
		step := newLotteryCampaignStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

